head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05247.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID());
scwin.vBzProcsNo = "";
scwin.vListEligtyTpCd = "F";
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분
scwin.pMngId = js_id;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //로그인 ID

/**
 *	상장적격성 실질심사 내역
 */
scwin.fn_list_sync = function() {
    var strIsurCd, strIsurNm = "";
    var arrPar = new Array();
    if (scwin.fn_GetPar != undefined) {
        scwin.fn_GetPar(arrPar);
        strIsurCd = (arrPar.length >= 1 ? arrPar[0] : "");
        strIsurNm = (arrPar.length >= 1 ? arrPar[1] : "");
    }
    txb_ISUR_CD.setValue(strIsurCd);
    txb_COM_NM.setValue(strIsurNm);
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgList&inputMessageId=REALINVSTG_DETAIL_LIST_NEW" + "&ISUR_CD=" + strIsurCd + "&LIST_ELIGTY_TP_CD=F";
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.grd_List_OnClick = async function(row, colid) {
    var arrPar = new Array();
    if (scwin.fn_SetPar != undefined) {
        arrPar[0] = {
            BZ_PROCS_NO: dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO")
        };
        scwin.fn_SetPar(arrPar);
    }
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var arrPar = new Array();
    /***************************************
    opener에  fn_GetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 업종조회후  최초 지정 코드값이 없는 상태
    opener에  fn_SetPar의 이름을 가진 함수가 있다면, 이 펑션에 인수를 넘겨 값을 채워 이용한다. 없다면 선택한 코드값과 코드명칭을 지정하지 않는다.
    ***************************************/
    var parentWin = $c.frame.path("../");
    if (parentWin != undefined) {
        scwin.fn_GetPar = parentWin.fn_GetParBzProcsNo;
        scwin.fn_SetPar = parentWin.fn_SetParBzProcsNo;
    }
    scwin.fn_list_sync();
};
